window.LESSONS=[
{id:1,unit:0,title:"你好，我的长笛",duration:"5 分钟",kind:"parts",goal:"认识弯头、吹孔和按键。",say:"这是你的音乐新朋友。弯弯的笛头，让吹孔离小手更近一点。",steps:["和大人一起，把笛盒平放在桌上打开。","找一找弯弯的笛头，再找小小的吹孔。","看看一排圆圆的按键。今天先轻轻观察。"],practice:"长笛找朋友",task:"声音从哪里开始呢？找出我们吹气的地方。",choices:["吹孔","笛盒","清洁布"],answer:0,feedback:"找到了！我们让气流掠过吹孔的边缘，来寻找声音。",parent:"按实际型号介绍笛头和笛身。有些儿童长笛的管节与按键不同，以自己的乐器为准。让孩子指出部位即可，不急着吹。",check:"能指出吹孔，并知道按键要轻轻对待。"},
{id:2,unit:0,title:"给长笛一个舒服的家",duration:"5 分钟",kind:"care",goal:"练习安全取放和练后收好。",say:"长笛也需要被温柔照顾。握住没有按键的管子，让大人陪你慢慢来。",steps:["请大人先示范：拿没有按键的管段，不用手挤压按键。","组装时让大人扶好、对齐。遇到卡住，就先停下来。","练完请大人按说明清洁，再把长笛放回自己的位置。"],practice:"温柔的小选择",task:"组装时，应该握哪里？",choices:["紧紧抓住按键","没有按键的管段","拉住细细的连杆"],answer:1,feedback:"对啦，握住合适的无按键管段，让大人帮助你。",parent:"成人负责初期组装。弯管的清洁方法按厂家说明，避免强行插入清洁杆；不拧螺丝、不挤按键。",check:"知道卡住时停下，并请大人帮忙。"},
{id:3,unit:0,title:"小树站稳，肩膀放松",duration:"5 分钟",kind:"posture",goal:"找到脚踏实、头自然、肩膀放松的感觉。",say:"像一棵舒服的小树，脚踩稳，头轻轻长高，肩膀不用往上跑。",steps:["先不拿长笛，双脚舒服地踩在地上。坐着时也让脚有支撑。","耸一下肩，再慢慢放下，感觉肩膀变松。","请大人帮你拿好长笛；按老师调整的角度，短短试一会儿。"],practice:"舒服，还是不舒服？",task:"手臂已经累了，我们可以怎么做？",choices:["再坚持很久","先放下长笛休息","把肩膀越抬越高"],answer:1,feedback:"当然可以休息。舒服的小身体，才能慢慢学会音乐。",parent:"此图只提示放松与站坐，不规定弯头旋转角度、支点或手臂角度。请老师根据孩子本人和具体型号调整。",check:"能说出哪里累，愿意及时放下乐器。"},
{id:4,unit:0,title:"准备出发的小音乐家",duration:"6 分钟",kind:"listen",goal:"复习取放和姿势，听一听声音的高低。",say:"今天我们做个小侦探。耳朵听一听，身体也检查一下：我舒服吗？",steps:["指出吹孔，再请大人帮助检查长笛是否放稳。","把肩膀放松，脚踏实；还不用开始吹。","点一下“听示范”，听两个声音：后一个更高，还是更低？"],demo:["G4","B4"],practice:"声音往哪里走？",task:"听过示范后，选一选。",choices:["第二个声音更高","第二个声音更低"],answer:0,feedback:"耳朵发现了：第二个声音更高。高低和响不响是两件事。",parent:"示范使用相近响度的电子音，只用于听辨音高。可以重复播放，不要求孩子记音名。",check:"能初步听出高低，并复习舒服的准备动作。"},
{id:5,unit:1,title:"让小气流去旅行",duration:"5 分钟",kind:"air",goal:"在成人陪伴下，用笛头探索发声。",say:"下唇轻轻靠着唇板，让一小股气流掠过吹孔的边缘。我们一起找找声音。",steps:["先请老师示范并确认吹孔和下唇的位置；家长陪同练习。","自然吸一口气，短短试吹一下。先不组装整支笛。","如果只有气声，就停一下，再小幅调整位置试试。"],practice:"今天的小发现",task:"暂时只有气声，应该怎么办？",choices:["用力猛吹","休息后，轻轻调整再试"],answer:1,feedback:"找声音需要一点时间。轻轻调整，每次只试短短一下。",parent:"气流图是方向概念示意，不是口型的精确角度模板。初学者发声需个别调整；不要求微笑拉紧嘴角，不做憋气比赛。",check:"愿意尝试，并能在短练习之间自然休息。"},
{id:6,unit:1,title:"我还能再找到它",duration:"5 分钟",kind:"air",goal:"在休息后，再次找到刚才的声音。",say:"刚才的声音很可爱。放下笛头歇一歇，我们再邀请它来一次。",steps:["找到声音后，记住下唇接触唇板的舒服感觉。","放下笛头，自然呼吸，再按刚才的位置试一次。","做两三次短尝试，哪一次更容易？和大人说说。"],practice:"给自己一片小叶子",task:"你今天有什么发现？每个发现都值得记住。",choices:["我找到一次声音","我知道还想试哪里","今天想先休息"],answer:"any",feedback:"发现已经收好。学音乐可以慢慢来，我们下一次再试。",parent:"以能重复找到声音为方向，不限定必须几秒或本课完成。持续只有气声时请老师检查口型与笛头，不靠增加练习时长解决。",check:"能在休息后重新尝试，或说出自己的感受。"},
{id:7,unit:1,title:"声音也会走小步",duration:"6 分钟",kind:"rhythm",goal:"模仿短声音、稍长的声音和停顿。",say:"短短一声，长一点点，再安静一下。声音也可以走出不同的脚步。",steps:["先用嘴说“嘟——嘟”，再拍拍同样的节奏。","听电子示范：短、短、长一点点。用拍手模仿。","请老师示范轻吐音，再在笛头上短短试一下。安静时正常呼吸。"],demo:["B4","B4","B4"],durations:[.35,.35,.75],practice:"听完，再试一次",task:"声音变长了，是不是就一定更响？",choices:["是，越长越响","不是，长短与强弱不同"],answer:1,feedback:"对啦，声音可以又长又轻。今天只玩长短，不需要吹得很响。",parent:"这里先用图形感受时长，不背音符定义。轻吐音应由老师示范；保持气流自然，避免用力顶舌。",check:"能拍出短、短、稍长的节奏。"},
{id:8,unit:1,title:"你一句，我一句",duration:"6 分钟",kind:"rhythm",goal:"听完一个短声音句子，再回应。",say:"我说一句音乐，你也说一句音乐。先听完，再轮到你。",steps:["点示范，先听两遍：短、长、短。","用拍手回应，安静的时候也等一等。","如果笛头发声已稳定，就吹一个自己的声音句子。"],demo:["B4","B4","B4"],durations:[.3,.6,.3],practice:"轮到谁说话？",task:"大人的音乐句子还没有结束，我们先做什么？",choices:["认真听完","马上一起吹得更响"],answer:0,feedback:"先听完，再回应。你已经开始和别人一起玩音乐了。",parent:"一次模仿两三个声音即可。可交替用拍手、哼唱和笛头，避免一直举着乐器。",check:"能等待示范结束，再模仿一个短句。"},
{id:9,unit:2,title:"B 住在第三条线",duration:"7 分钟",kind:"note",note:"B4",goal:"认识 B4 的谱位、声音和基本指法。",say:"五线谱有五条线。从下面数，B 的小脑袋坐在第三条线上。",steps:["先数五条线，再找线中间的四个空隙。看到前面的高音谱号了吗？","点 B 听声音，再看指法图：左拇指、左食指按下；通常右小指也按下。","由老师确认支点后，轻轻吹 B。只短短试几次，然后休息。"],demo:["B4"],practice:"B 的小房子",task:"从下面数，B4 在哪里？",choices:["第一条线","第三条线","第五条线"],answer:1,feedback:"找到啦！B4 的符头被第三条线穿过。",parent:"指法图采用常见波姆体系长笛：左拇指使用 B 本位音键，不是降 B 拇指键。右小指通常按降 E 键；儿童特殊型号由老师确认。",check:"能找到 B4 的谱位，并在帮助下尝试正确指法。"},
{id:10,unit:2,title:"A 住在第二个间",duration:"7 分钟",kind:"note",note:"A4",goal:"认识 A4，并与 B4 对比。",say:"A 住在线和线的中间。从下面数，它在第二个间里，比 B 低一点。",steps:["先找到昨天的 B，再往下一小步，找到 A。","点 A 和 B 听一听。看指法图：在 B 的基础上，再按左中指。","先不吹气，轻轻换 B、A 的手指，再试两个短声音。"],demo:["B4","A4"],practice:"A 在哪里？",task:"从下面数，A4 住在……",choices:["第二个间","第三条线","第四个间"],answer:0,feedback:"对啦，A4 在第二间。间就是两条线中间的空隙。",parent:"左拇指、左食指、左中指及通常按下的右小指参与 A4 指法。保持原先支点，换指不需要抬得很高。",check:"能分清 B 在线上、A 在间里。"},
{id:11,unit:2,title:"G 坐上第二条线",duration:"7 分钟",kind:"note",note:"G4",goal:"认识 G4，连接 B4、A4、G4。",say:"再往下一小步，就遇见 G。它坐在第二条线上，高音谱号也会帮我们认出它。",steps:["从最下面数：第一条线、第二条线。G 的符头就在这里。","在 A 的基础上，再按左无名指。保持右手轻轻支撑。","先静默换指，再慢慢试 B、A、G。每个音之间可以休息。"],demo:["B4","A4","G4"],practice:"给 G 找位置",task:"G4 的符头坐在哪里？",choices:["第二个间","第二条线","第三条线"],answer:1,feedback:"找到 G 了！高音谱号的中心卷曲围着的，也是这条线。",parent:"G4 使用左拇指、左食指、中指、无名指及通常按下的右小指。左手按键增加时留意握紧与耸肩，必要时先静默练习。",check:"能把 G4 的声音、谱位和指法联系起来。"},
{id:12,unit:2,title:"三位朋友的小旅行",duration:"8 分钟",kind:"melody",goal:"读出并尝试一段 B、A、G 小旋律。",say:"B、A、G 都来了！让我们看着谱，一步一步，把它们连成小音乐。",steps:["指着谱，慢慢说出 B、A、G 的名字，先不吹。","听示范，再跟着做静默指法。也可以一小句一小句练。","选舒服的速度吹一遍。哪里想再试，就只练那一小段。"],demo:["B4","A4","G4","A4","B4","A4","G4"],practice:"我想分享的小发现",task:"今天最想告诉家人什么？",choices:["我认出了三个音","我吹出一小段音乐","我想再玩一次"],answer:"any",feedback:"每一种发现都很好。你可以把这段音乐送给家人听。",parent:"谱面使用等长音符展示音序，正式时值在下一单元学习。此时允许停顿与分句；不要求一口气吹完，也不以电子音色为模仿目标。",check:"能读出三音片段，尝试分句吹奏。"}
];
